-- amethyst / prison life private client. generated by tools/build_private.py
-- paste this whole file into a Luau executor while in an official private server.
-- no external HTTP loader, no installed server scripts, no public-server execution.
-- Maid.
local function loadMaid()
local Maid = {}
Maid.__index = Maid

---Create an owner for temporary connections and instances.
---@return table
function Maid.new()
	return setmetatable({tasks = {}}, Maid)
end

---Register a cleanup task for a feature's lifetime.
---@param task any
---@return any
function Maid:give(task)
	table.insert(self.tasks, task)
	return task
end

---Release connections before their instances to avoid stale callbacks.
function Maid:clean()
	local tasks = self.tasks
	self.tasks = {}
	for index = #tasks, 1, -1 do
		local item = tasks[index]
		local kind = typeof(item)
		if kind == "RBXScriptConnection" then
			item:Disconnect()
		elseif kind == "Instance" then
			item:Destroy()
		elseif type(item) == "function" then
			local ok, errorMessage = pcall(item)
			if not ok then warn("[amethyst] cleanup failed:", errorMessage) end
		elseif type(item) == "table" and type(item.destroy) == "function" then
			item:destroy()
		end
	end
end

return Maid
end
local Maid = loadMaid()

-- Theme.
local function loadTheme()
local Theme = {}

-- A single black-and-violet palette keeps every control visually consistent.
Theme.colors = {
	background = Color3.fromRGB(16, 13, 25),
	surface = Color3.fromRGB(28, 23, 41),
	deep = Color3.fromRGB(22, 18, 32),
	raised = Color3.fromRGB(42, 34, 58),
	border = Color3.fromRGB(72, 57, 100),
	violet = Color3.fromRGB(143, 99, 238),
	violetLight = Color3.fromRGB(190, 156, 255),
	violetDark = Color3.fromRGB(90, 56, 165),
	text = Color3.fromRGB(245, 240, 255),
	muted = Color3.fromRGB(167, 154, 192),
	track = Color3.fromRGB(14, 12, 22),
}

-- Services.
local tweenService = game:GetService("TweenService")

---Build a native Roblox GUI object with its parent assigned last.
---@param className string
---@param properties table
---@param parent Instance
---@return Instance
function Theme.create(className, properties, parent)
	local object = Instance.new(className)
	for key, value in pairs(properties) do
		object[key] = value
	end
	object.Parent = parent
	return object
end

---Give a surface the small rounded corners used in the reference layout.
---@param parent GuiObject
---@param radius number
function Theme.corner(parent, radius)
	Theme.create("UICorner", {CornerRadius = UDim.new(0, radius)}, parent)
end

---Separate adjacent panels without adding another accent color.
---@param parent GuiObject
---@param color Color3?
function Theme.stroke(parent, color)
	Theme.create("UIStroke", {
		Color = color or Theme.colors.border,
		Thickness = 1,
		Transparency = 0.2,
	}, parent)
end

---Use quick, unobtrusive animations for state changes and layout transitions.
---@param object Instance
---@param properties table
---@param duration number?
function Theme.tween(object, properties, duration)
	local tween = tweenService:Create(object, TweenInfo.new(duration or 0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), properties)
	tween:Play()
	return tween
end

return Theme
end
local Theme = loadTheme()

-- Library.
local function loadLibrary(ThemeModule, MaidModule)
local Library = {}
Library.__index = Library

-- Services.
local userInputService = game:GetService("UserInputService")

-- Both dependencies are injected by the single-file builder.
local Theme = ThemeModule
local Maid = MaidModule

local Colors = Theme.colors
local HEADER_HEIGHT = 44

local function createText(parent, text, position, size, font, textSize, color, alignment)
	return Theme.create("TextLabel", {
		BackgroundTransparency = 1,
		Position = position,
		Size = size,
		Text = tostring(text):lower(),
		TextColor3 = color or Colors.text,
		Font = font or Enum.Font.Gotham,
		TextSize = textSize or 13,
		TextXAlignment = alignment or Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
	}, parent)
end

local function onCallbackError(errorMessage)
	warn("[amethyst] gui action failed:", errorMessage)
	if debug and type(debug.traceback) == "function" then warn(debug.traceback()) end
end

