local BOUNDS = {
	aimFov = {35, 350}, aimSmooth = {0.04, 1}, movementSpeed = {16, 120},
	flySpeed = {12, 100}, gunDamage = {1, 100}, gunInterval = {0.05, 1},
	gunSpread = {0, 8}, vehicleSpeed = {10, 120}, vehicleHandling = {0.5, 4},
}
local KEY_FIELDS = {menuKey = true, aimKey = true, fireKey = true, stopKey = true,
	flightUpKey = true, flightDownKey = true}

local function sanitize(input)
	local result = {}
	for key, default in pairs(DEFAULTS) do
		local value = type(input) == "table" and input[key] or nil
		if type(default) == "boolean" and type(value) == "boolean" then
			result[key] = value
		elseif BOUNDS[key] and type(value) == "number" and value == value and math.abs(value) < math.huge then
			result[key] = math.clamp(value, BOUNDS[key][1], BOUNDS[key][2])
		elseif KEY_FIELDS[key] and type(value) == "string" and #value <= 20 then
			local valid, enum = pcall(function() return Enum.KeyCode[value] end)
			result[key] = valid and enum and enum ~= Enum.KeyCode.None
				and enum ~= Enum.KeyCode.Escape and value or default
		else
			result[key] = default
		end
	end
	if type(input) == "table" and (input.aimPart == "Head" or input.aimPart == "HumanoidRootPart") then
		result.aimPart = input.aimPart
	end
	-- A loaded file must not make emergency stop or any other binding unreachable.
	local used = {}
	for _, key in ipairs({"stopKey", "menuKey", "aimKey", "fireKey", "flightUpKey", "flightDownKey"}) do
		local value = result[key]
		if used[value] then
			value = DEFAULTS[key]
			if used[value] then
				for _, candidate in ipairs({"RightShift", "E", "G", "Z", "Space", "LeftControl", "F", "H", "Q", "X"}) do
					if not used[candidate] then value = candidate; break end
				end
			end
			result[key] = value
		end
		used[value] = true
	end
	return result
end

local function getRig(player)
	local character = player.Character
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	local root = character and character:FindFirstChild("HumanoidRootPart")
	if not (humanoid and humanoid.Health > 0 and root and root:IsA("BasePart")) then return nil end
	return character, humanoid, root
end

local function inPrivateServer()
	local ok, id, ownerId = pcall(function()
		return game.PrivateServerId, game.PrivateServerOwnerId
	end)
	-- Reserved servers also have an ID; owner > 0 restricts this build to private/VIP servers.
	return ok and type(id) == "string" and id ~= "" and type(ownerId) == "number" and ownerId > 0
end

Context.playersService = playersService
Context.replicatedStorage = replicatedStorage
Context.userInputService = userInputService
Context.runService = runService
Context.httpService = httpService
Context.globalState = globalState
Context.SAVE_PATH = SAVE_PATH
Context.PRISON_LIFE_PLACE_ID = PRISON_LIFE_PLACE_ID
Context.FREE_WEAPONS = FREE_WEAPONS
Context.KEY_FIELDS = KEY_FIELDS
Context.sanitize = sanitize
Context.getRig = getRig
Context.inPrivateServer = inPrivateServer

return Context
end
local PrivateContext = loadPrivateContext()

-- Targeting.
local function loadTargeting(PrivateContextModule)
local playersService = PrivateContextModule.playersService
local userInputService = PrivateContextModule.userInputService
local getRig = PrivateContextModule.getRig

-- Targeting uses viewport-space distance and optional team/visibility checks.
local Targeting = {}
Targeting.__index = Targeting

function Targeting.new(hub)
	return setmetatable({hub = hub, selected = nil}, Targeting)
end

function Targeting:part(player)
	if player == self.hub.localPlayer or player.Parent ~= playersService then return nil end
	local character, humanoid, root = getRig(player)
	if not character then return nil end
	if self.hub.config.teamCheck and player.Team ~= nil and player.Team == self.hub.localPlayer.Team then return nil end
	local part = character:FindFirstChild(self.hub.config.aimPart) or root
	if not (part and part:IsA("BasePart")) then return nil end
	if self.hub.config.wallCheck then
		local camera = workspace.CurrentCamera
		if not camera then return nil end
		local parameters = RaycastParams.new()
		parameters.FilterType = Enum.RaycastFilterType.Exclude
		parameters.FilterDescendantsInstances = {self.hub.localPlayer.Character}
		local result = workspace:Raycast(camera.CFrame.Position, part.Position - camera.CFrame.Position, parameters)
		if result and not result.Instance:IsDescendantOf(character) then return nil end
	end
	return part
end

---Pick the closest visible player within the configurable cursor FOV.
---@return Player?
function Targeting:getClosestPlayer()
	local camera = workspace.CurrentCamera
	if not camera then return nil end
	local mousePosition = userInputService.MouseEnabled and userInputService:GetMouseLocation() or camera.ViewportSize / 2
	local closest, closestDistance = nil, self.hub.config.aimFov
	for _, player in ipairs(playersService:GetPlayers()) do
		if player == self.hub.localPlayer then continue end
		local part = self:part(player)
		if not part then continue end
		local screenPosition, onScreen = camera:WorldToViewportPoint(part.Position)
		if not onScreen or screenPosition.Z <= 0 then continue end
		local distance = (Vector2.new(screenPosition.X, screenPosition.Y) - mousePosition).Magnitude
		if distance < closestDistance then closest, closestDistance = player, distance end
	end
	return closest
end

function Targeting:get()
	if self.selected and self:part(self.selected) then return self.selected end
	return self:getClosestPlayer()
end

function Targeting:nearestCriminal(maximum)
	local _, _, ownRoot = getRig(self.hub.localPlayer)
	if not ownRoot then return nil end
	local selected = self.selected
	local function distanceTo(player)
		if not (player and player.Team and player.Team.Name:lower():find("criminal", 1, true)) then return nil end
		local _, _, root = getRig(player)
		if not root then return nil end
		local distance = (root.Position - ownRoot.Position).Magnitude
		return distance <= maximum and self:part(player) and distance or nil
	end
	if distanceTo(selected) then return selected end
	local nearest, best = nil, maximum
	for _, player in ipairs(playersService:GetPlayers()) do
		local distance = distanceTo(player)
		if distance and distance < best then nearest, best = player, distance end
	end
	return nearest
end

return Targeting
end
local Targeting = loadTargeting(PrivateContext)

-- Movement.
local function loadMovement(PrivateContextModule, MaidModule)
local Maid = MaidModule
local runService = PrivateContextModule.runService
local userInputService = PrivateContextModule.userInputService
local getRig = PrivateContextModule.getRig

-- Character movement is local; the game server may correct unsupported modes.
local Movement = {}
Movement.__index = Movement

function Movement.new(hub)
	local self = setmetatable({hub = hub, maid = Maid.new(), modeMaid = Maid.new(),
		flightMaid = Maid.new(), collisions = {}, speedBefore = nil,
		flightCharacter = nil, up = false, down = false}, Movement)
	self.maid:give(hub.localPlayer.CharacterAdded:Connect(function(character)
		self:stopFlight()
		self:restoreCollisions()
		self.speedBefore = nil
		task.spawn(function()
			character:WaitForChild("HumanoidRootPart", 7)
			if self.hub.localPlayer.Character == character then self:configure() end
		end)
	end))
	return self
end

function Movement:restoreCollisions()
	for part, oldValue in pairs(self.collisions) do
		if part.Parent then part.CanCollide = oldValue end
	end
	self.collisions = {}
end

function Movement:stopFlight()
	self.flightMaid:clean()
	if self.flightHumanoid and self.flightHumanoid.Parent then
		self.flightHumanoid.PlatformStand = self.oldPlatformStand
		self.flightHumanoid.AutoRotate = self.oldAutoRotate
		if self.flightHumanoid.Health > 0 then self.flightHumanoid:ChangeState(Enum.HumanoidStateType.GettingUp) end
	end
	self.flightCharacter, self.flightHumanoid, self.flightVelocity = nil, nil, nil
	self.up, self.down = false, false
end

function Movement:stepFlight()
	local humanoid, velocity = self.flightHumanoid, self.flightVelocity
	if not (humanoid and humanoid.Health > 0 and velocity and velocity.Parent) then self:stopFlight(); return end
	local move = humanoid.MoveDirection
	local camera = workspace.CurrentCamera
	if move.Magnitude < 0.05 and camera and self.controls then
		-- Standard PlayerModule exposes the mobile thumbstick even in PlatformStand.
		local ok, vector = pcall(self.controls.GetMoveVector, self.controls)
		if ok and typeof(vector) == "Vector3" then
			move = camera.CFrame.RightVector * vector.X - camera.CFrame.LookVector * vector.Z
		end
	end
	if move.Magnitude < 0.05 and camera and not userInputService:GetFocusedTextBox() then
		local forward = (userInputService:IsKeyDown(Enum.KeyCode.W) and 1 or 0) - (userInputService:IsKeyDown(Enum.KeyCode.S) and 1 or 0)
		local sideways = (userInputService:IsKeyDown(Enum.KeyCode.D) and 1 or 0) - (userInputService:IsKeyDown(Enum.KeyCode.A) and 1 or 0)
		move = camera.CFrame.LookVector * forward + camera.CFrame.RightVector * sideways
	end
	local up = Enum.KeyCode[self.hub.config.flightUpKey]
	local down = Enum.KeyCode[self.hub.config.flightDownKey]
	local vertical = ((self.up or userInputService:IsKeyDown(up)) and 1 or 0)
		- ((self.down or userInputService:IsKeyDown(down)) and 1 or 0)
	local direction = Vector3.new(move.X, vertical, move.Z)
	velocity.VectorVelocity = (direction.Magnitude > 1 and direction.Unit or direction) * self.hub.config.flySpeed
end

function Movement:startFlight()
	local character, humanoid, root = getRig(self.hub.localPlayer)
	if not character or self.flightCharacter == character then return end
	self:stopFlight()
	self.flightCharacter, self.flightHumanoid = character, humanoid
	self.oldPlatformStand, self.oldAutoRotate = humanoid.PlatformStand, humanoid.AutoRotate
	local playerScripts = self.hub.localPlayer:FindFirstChild("PlayerScripts")
	local playerModule = playerScripts and playerScripts:FindFirstChild("PlayerModule")
	if playerModule then
		local ok, module = pcall(require, playerModule)
		if ok and type(module) == "table" and type(module.GetControls) == "function" then
			local controlsOk, controls = pcall(module.GetControls, module)
			if controlsOk and controls and type(controls.GetMoveVector) == "function" then
				self.controls = controls
			end
		end
	end
	local attachment = Instance.new("Attachment")
	attachment.Name = "amethyst flight"
	attachment.Parent = root
	self.flightMaid:give(attachment)
	local velocity = Instance.new("LinearVelocity")
	velocity.Attachment0 = attachment
	velocity.RelativeTo = Enum.ActuatorRelativeTo.World
	velocity.VelocityConstraintMode = Enum.VelocityConstraintMode.Vector
	velocity.MaxForce = 1000000
	velocity.ForceLimitsEnabled = false
	velocity.VectorVelocity = Vector3.zero
	velocity.Parent = root
	self.flightMaid:give(velocity)
	self.flightVelocity = velocity
	humanoid.PlatformStand, humanoid.AutoRotate = true, false
	self.flightMaid:give(runService.Heartbeat:Connect(function() self:stepFlight() end))
end

function Movement:configure()
	self.modeMaid:clean()
	local character, humanoid = getRig(self.hub.localPlayer)
	if self.hub.config.speedEnabled and humanoid then
		self.speedBefore = self.speedBefore or humanoid.WalkSpeed
		local function applySpeed()
			if humanoid.Parent and humanoid.WalkSpeed ~= self.hub.config.movementSpeed then
				humanoid.WalkSpeed = self.hub.config.movementSpeed
			end
		end
		applySpeed()
		self.modeMaid:give(humanoid:GetPropertyChangedSignal("WalkSpeed"):Connect(applySpeed))
	elseif self.speedBefore and humanoid then
		humanoid.WalkSpeed = self.speedBefore
		self.speedBefore = nil
	end
	if self.hub.config.noclip and character then
		local function disableCollision(part)
			if not part:IsA("BasePart") then return end
			if self.collisions[part] == nil then self.collisions[part] = part.CanCollide end
			part.CanCollide = false
		end
		for _, part in ipairs(character:GetDescendants()) do disableCollision(part) end
		self.modeMaid:give(character.DescendantAdded:Connect(disableCollision))
		self.modeMaid:give(runService.Stepped:Connect(function()
			for part in pairs(self.collisions) do
				if part:IsDescendantOf(character) then part.CanCollide = false
				else self.collisions[part] = nil end
			end
		end))
	else
		self:restoreCollisions()
	end
	if self.hub.config.infiniteJump then
		self.modeMaid:give(userInputService.JumpRequest:Connect(function()
			local _, rig = getRig(self.hub.localPlayer)
			if rig and not self.hub.config.fly then rig:ChangeState(Enum.HumanoidStateType.Jumping) end
		end))
	end
	if self.hub.config.antiStun and humanoid then
		local function clearStun()
			if humanoid.Parent and not self.hub.config.fly and humanoid.PlatformStand then humanoid.PlatformStand = false end
		end
		self.modeMaid:give(humanoid:GetPropertyChangedSignal("PlatformStand"):Connect(clearStun))
		clearStun()
	end
	if self.hub.config.fly then self:startFlight() else self:stopFlight() end
end

function Movement:destroy()
	self.hub.config.speedEnabled = false
	self.hub.config.fly = false
	self.hub.config.noclip = false
	self.hub.config.infiniteJump = false
	self.hub.config.antiStun = false
	self.maid:clean()
	self:configure()
	self.modeMaid:clean()
	self:stopFlight()
	self:restoreCollisions()
end

return Movement
end
local Movement = loadMovement(PrivateContext, Maid)

-- Visuals.
local function loadVisuals(PrivateContextModule, MaidModule, ThemeModule)
local Maid = MaidModule
local Theme = ThemeModule
local playersService = PrivateContextModule.playersService
local runService = PrivateContextModule.runService
local getRig = PrivateContextModule.getRig

-- ESP uses Roblox GUI objects on both mobile and desktop; Drawing is optional.
local Visuals = {}
Visuals.__index = Visuals

function Visuals.new(hub)
	return setmetatable({hub = hub, maid = Maid.new(), markers = {}, watched = {}}, Visuals)
end

function Visuals:remove(key)
	local marker = self.markers[key]
	if not marker then return end
	marker.highlight:Destroy()
	marker.billboard:Destroy()
	self.markers[key] = nil
end

function Visuals:add(key, model, part, label)
	if self.markers[key] then return end
	local highlight = Instance.new("Highlight")
	highlight.Adornee = model
	highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
	highlight.FillColor = Theme.colors.violet
	highlight.FillTransparency = 0.84
	highlight.OutlineColor = Theme.colors.violetLight
	highlight.Parent = self.hub.playerGui
	local billboard = Instance.new("BillboardGui")
	billboard.Adornee = part
	billboard.AlwaysOnTop = true
	billboard.MaxDistance = 450
	billboard.Size = UDim2.fromOffset(210, 48)
	billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
	billboard.Parent = self.hub.playerGui
	local text = Instance.new("TextLabel")
	text.Size = UDim2.fromScale(1, 1)
	text.BackgroundTransparency = 1
	text.TextColor3 = Theme.colors.violetLight
	text.TextStrokeTransparency = 0.15
	text.Font = Enum.Font.GothamBold
	text.TextSize = 13
	text.Text = label:lower()
	text.Parent = billboard
	self.markers[key] = {highlight = highlight, billboard = billboard, text = text,
		model = model, part = part, label = label:lower()}
end

function Visuals:watchPlayer(player)
	if player == self.hub.localPlayer or self.watched[player] then return end
	local maid = Maid.new()
	self.watched[player] = maid
	local function onCharacter(character)
		task.spawn(function()
			local head = character:WaitForChild("Head", 5)
			if self.hub.config.playerEsp and player.Character == character and head and head:IsA("BasePart") then
				self:remove(player)
				self:add(player, character, head, player.DisplayName .. " @" .. player.Name)
			end
		end)
	end
	maid:give(player.CharacterAdded:Connect(onCharacter))
	maid:give(player.CharacterRemoving:Connect(function() self:remove(player) end))
	if player.Character then onCharacter(player.Character) end
end

function Visuals:watchSeat(seat)
	if not (seat:IsA("VehicleSeat") and seat:IsDescendantOf(workspace)) then return end
	local model = seat:FindFirstAncestorOfClass("Model") or seat
	self:add(seat, model, seat, "vehicle · " .. model.Name)
end

function Visuals:configure()
	self.maid:clean()
	local oldMarkers, oldWatchers = self.markers, self.watched
	self.markers, self.watched = {}, {}
	for _, marker in pairs(oldMarkers) do
		marker.highlight:Destroy()
		marker.billboard:Destroy()
	end
	for _, maid in pairs(oldWatchers) do maid:clean() end
	if self.hub.config.playerEsp then
		for _, player in ipairs(playersService:GetPlayers()) do self:watchPlayer(player) end
		self.maid:give(playersService.PlayerAdded:Connect(function(player) self:watchPlayer(player) end))
		self.maid:give(playersService.PlayerRemoving:Connect(function(player)
			self:remove(player)
			local maid = self.watched[player]
			if maid then maid:clean(); self.watched[player] = nil end
		end))
	end
	if self.hub.config.vehicleEsp then
		for _, object in ipairs(workspace:GetDescendants()) do
			if object:IsA("VehicleSeat") then self:watchSeat(object) end
		end
		self.maid:give(workspace.DescendantAdded:Connect(function(object)
			if object:IsA("VehicleSeat") then self:watchSeat(object) end
		end))
	end
	if self.hub.config.playerEsp or self.hub.config.vehicleEsp then
		local elapsed = 0
		self.maid:give(runService.Heartbeat:Connect(function(delta)
			elapsed += delta
			if elapsed < 0.2 then return end
			elapsed = 0
			local _, _, root = getRig(self.hub.localPlayer)
			for key, marker in pairs(self.markers) do
				if not marker.part:IsDescendantOf(workspace) or not marker.model:IsDescendantOf(workspace) then
					self:remove(key)
				else
					local distance = root and math.floor((root.Position - marker.part.Position).Magnitude) or 0
					marker.text.Text = marker.label .. " · " .. distance .. " studs"
				end
			end
		end))
	end
end

function Visuals:destroy()
	self.hub.config.playerEsp, self.hub.config.vehicleEsp = false, false
	self:configure()
end

return Visuals
end
local Visuals = loadVisuals(PrivateContext, Maid, Theme)

-- Combat.
local function loadCombat(PrivateContextModule, MaidModule)
local Maid = MaidModule
local replicatedStorage = PrivateContextModule.replicatedStorage
local runService = PrivateContextModule.runService
local globalState = PrivateContextModule.globalState
local getRig = PrivateContextModule.getRig
local inPrivateServer = PrivateContextModule.inPrivateServer

-- Combat only observes a known shot packet shape; unrecognized calls pass through.
local Combat = {}
Combat.__index = Combat

function Combat.new(hub)
	return setmetatable({hub = hub, maid = Maid.new(), aimHeld = false,
		autoElapsed = 0, tazeElapsed = 0, pendingArrest = false,
		shotStatus = "not installed", shotsSeen = 0, shotsChanged = 0,
		warnedPacket = false, warnedArrest = false}, Combat)
end

function Combat:aim(delta)
	local config = self.hub.config
	if not (config.aimlock or (config.aimbot and self.aimHeld)) then return end
	local camera = workspace.CurrentCamera
	local player = self.hub.targeting:get()
	local part = player and self.hub.targeting:part(player)
	if not (camera and part) then return end
	local target = CFrame.lookAt(camera.CFrame.Position, part.Position)
	camera.CFrame = camera.CFrame:Lerp(target, math.clamp(config.aimSmooth * delta * 60, 0, 1))
end

function Combat:activate()
	local character = self.hub.localPlayer.Character
	local tool = character and character:FindFirstChildOfClass("Tool")
	if not tool then return false, "equip a tool first" end
	local ok, errorMessage = pcall(tool.Activate, tool)
	return ok, ok and "tool activated locally; server result unconfirmed" or tostring(errorMessage)
end

function Combat:redirectShot(args)
	if not (self.hub.config.silentAim and inPrivateServer()) then return nil end
	self.shotsSeen += 1
	local packet, tool = args[1], args[2]
	local character = self.hub.localPlayer.Character
	local compatible = type(packet) == "table" and type(packet[1]) == "table"
		and typeof(tool) == "Instance" and tool:IsA("Tool")
		and tool:FindFirstChild("GunStates") and character and tool:IsDescendantOf(character)
	if compatible then
		for _, shot in ipairs(packet) do
			if type(shot) ~= "table" or typeof(shot.Cframe) ~= "CFrame"
				or typeof(shot.RayObject) ~= "Ray" or type(shot.Distance) ~= "number"
				or (shot.Hit ~= nil and typeof(shot.Hit) ~= "Instance") then
				compatible = false
				break
			end
		end
	end
	if not compatible then
		self.shotStatus = "unrecognized shot packet; passing through"
		if not self.warnedPacket then
			self.warnedPacket = true
			self.hub:notify("silent aim: shot packet is not compatible", false)
		end
		return nil
	end
	local player = self.hub.targeting:get()
	local part = player and self.hub.targeting:part(player)
	if not part then self.shotStatus = "compatible packet; no eligible target"; return nil end
	local root = character:FindFirstChild("HumanoidRootPart")
	local handle = tool:FindFirstChild("Handle")
	local replacement = {}
	for index, shot in ipairs(packet) do
		local origin = shot.RayObject.Origin
		if not root then return nil end
		if (origin - root.Position).Magnitude > 100 then
			origin = handle and handle:IsA("BasePart") and handle.Position or root.Position
		end
		local direction = part.Position - origin
		if direction.Magnitude < 0.01 or direction.Magnitude > 800 then
			self.shotStatus = "target outside supported range"
			return nil
		end
		local copy = table.clone(shot)
		copy.Hit = part
		copy.Distance = direction.Magnitude
		copy.Cframe = CFrame.lookAt(origin, part.Position)
		copy.RayObject = Ray.new(origin, direction)
		replacement[index] = copy
	end
	local copied = table.pack(table.unpack(args, 1, args.n))
	copied[1] = replacement
	self.shotsChanged += 1
	self.shotStatus = "packet redirected; server hit unconfirmed"
	return copied
end

function Combat:enableSilentAim()
	if not (type(hookmetamethod) == "function" and type(getnamecallmethod) == "function") then
		return false, "executor does not support a namecall hook"
	end
	local remote = replicatedStorage:FindFirstChild("ShootEvent")
	if not (remote and remote:IsA("RemoteEvent")) then return false, "compatible shot event not found" end
	local state = globalState.AmethystPrivateShotHook
	if type(state) ~= "table" or state.dataModel ~= game then
		state = {dataModel = game}
		local original
		local callback = function(self, ...)
			local methodOk, method = pcall(getnamecallmethod)
			local callerOk, fromExecutor = true, false
			if type(checkcaller) == "function" then callerOk, fromExecutor = pcall(checkcaller) end
			if methodOk and method == "FireServer" and self == state.remote and state.handler
				and callerOk and not fromExecutor then
				local ok, changed = pcall(state.handler, table.pack(...))
				if ok and changed then return original(self, table.unpack(changed, 1, changed.n)) end
			end
			return original(self, ...)
		end
		local ok, result = pcall(hookmetamethod, game, "__namecall",
			type(newcclosure) == "function" and newcclosure(callback) or callback)
		if not ok or type(result) ~= "function" then
			return false, "executor did not supply a usable namecall hook"
		end
		original = result
		globalState.AmethystPrivateShotHook = state
	end
	state.remote = remote
	state.handler = function(args) return self:redirectShot(args) end
	self.shotState = state
	self.shotStatus = "hook installed; waiting for a gun shot"
	return true, "shot hook installed; current game compatibility unverified"
end

function Combat:automate(delta)
	self.autoElapsed += delta
	self.tazeElapsed += delta
	if self.hub.config.rageBot and self.autoElapsed >= 0.5 then
		self.autoElapsed = 0
		local player = self.hub.targeting:get()
		local part = player and self.hub.targeting:part(player)
		local character = self.hub.localPlayer.Character
		local tool = character and character:FindFirstChildOfClass("Tool")
		local gunStates = tool and tool:FindFirstChild("GunStates")
		local camera = workspace.CurrentCamera
		if part and tool and gunStates and gunStates:IsA("ModuleScript") and camera then
			camera.CFrame = CFrame.lookAt(camera.CFrame.Position, part.Position)
			pcall(tool.Activate, tool)
		end
	end
	if not self.hub.config.autoTaze or self.tazeElapsed < 1.2 or self.pendingArrest then return end
	self.tazeElapsed = 0
	local target = self.hub.targeting:nearestCriminal(45)
	local character, _, root = target and getRig(target)
	if not (character and root) then return end
	local _, _, ownRoot = getRig(self.hub.localPlayer)
	if not ownRoot then return end
	local distance = (ownRoot.Position - root.Position).Magnitude
	if distance <= 10 then
		local remotes = workspace:FindFirstChild("Remote")
		local arrest = remotes and remotes:FindFirstChild("arrest")
		local head = character:FindFirstChild("Head")
		if not (arrest and arrest:IsA("RemoteFunction") and head) then return end
		self.pendingArrest = true
		task.spawn(function()
			local ok, accepted = pcall(arrest.InvokeServer, arrest, head)
			self.pendingArrest = false
			if self.hub.destroyed or not self.hub.config.autoTaze then return end
			if ok and accepted == true then
				self.hub:notify("arrest confirmed by remote", true)
			elseif not self.warnedArrest then
				self.warnedArrest = true
				self.hub:notify("arrest request not confirmed by server", false)
			end
		end)
	else
		local ownCharacter = self.hub.localPlayer.Character
		local tool = ownCharacter and ownCharacter:FindFirstChild("Taser")
		local camera = workspace.CurrentCamera
		local part = character:FindFirstChild("Head") or root
		if tool and tool:IsA("Tool") and camera then
			camera.CFrame = CFrame.lookAt(camera.CFrame.Position, part.Position)
			pcall(tool.Activate, tool)
		end
	end
end

function Combat:configure()
	self.maid:clean()
	local config = self.hub.config
	if config.aimbot or config.aimlock then
		local name = "amethyst private aim"
		runService:BindToRenderStep(name, Enum.RenderPriority.Camera.Value + 1, function(delta) self:aim(delta) end)
		self.maid:give(function() runService:UnbindFromRenderStep(name) end)
	end
	if config.rageBot or config.autoTaze then
		self.autoElapsed, self.tazeElapsed = 0, 0
		self.maid:give(runService.Heartbeat:Connect(function(delta) self:automate(delta) end))
	end
end

function Combat:destroy()
	self.maid:clean()
	if self.shotState and self.shotState.handler then self.shotState.handler = nil end
end

return Combat
end
local Combat = loadCombat(PrivateContext, Maid)

-- Travel.
local function loadTravel(PrivateContextModule)
local getRig = PrivateContextModule.getRig

-- Travel resolves live map objects; bookmark CFrames are local to this session.
local Travel = {}
Travel.__index = Travel

function Travel.new(hub)
	return setmetatable({hub = hub, bookmarks = {}, selected = nil}, Travel)
end

function Travel:listLocations()
	local result, seen = {}, {}
	for _, object in ipairs(workspace:GetDescendants()) do
		if object:IsA("SpawnLocation") and #result < 12 then
			local name = object.Name == "SpawnLocation" and "spawn · " .. object.TeamColor.Name or object.Name
			if not seen[name] then
				seen[name] = true
				table.insert(result, {name = name, kind = "map spawn", cframe = object.CFrame * CFrame.new(0, 4, 0)})
			end
		end
	end
	for name, destination in pairs(self.bookmarks) do
		table.insert(result, {name = name, kind = "saved location", cframe = destination})
	end
	table.sort(result, function(a, b) return a.name:lower() < b.name:lower() end)
	return result
end

function Travel:teleport(destination)
	if typeof(destination) ~= "CFrame" then return false, "invalid destination" end
	local character, humanoid, root = getRig(self.hub.localPlayer)
	if not character then return false, "character not ready" end
	local ok, errorMessage = pcall(function()
		humanoid.Sit = false
		character:PivotTo(destination)
		root.AssemblyLinearVelocity = Vector3.zero
	end)
	return ok, ok and "teleported locally; the server may correct this" or tostring(errorMessage)
end

function Travel:toPlayer(player)
	local _, _, root = getRig(player)
	if not root then return false, "player not ready" end
	return self:teleport(root.CFrame * CFrame.new(3, 0, 3))
end

function Travel:save(name)
	local _, _, root = getRig(self.hub.localPlayer)
	if not root then return false, "character not ready" end
	if type(name) ~= "string" then return false, "enter a bookmark name" end
	name = name:lower():match("^%s*(.-)%s*$"):sub(1, 24)
	if name == "" or not name:match("^[%w _%-]+$") then return false, "use letters, numbers, spaces, _ or -" end
	local count = 0
	for _ in pairs(self.bookmarks) do count += 1 end
	if count >= 8 and not self.bookmarks[name] then return false, "eight bookmarks maximum" end
	self.bookmarks[name] = root.CFrame
	return true, "saved " .. name
end

return Travel
end
local Travel = loadTravel(PrivateContext)

-- Inventory.
local function loadInventory(PrivateContextModule)
local FREE_WEAPONS = PrivateContextModule.FREE_WEAPONS

-- Item pickup calls are only made for actual game pickup objects in the map.
local Inventory = {}
Inventory.__index = Inventory

function Inventory.new(hub)
	return setmetatable({hub = hub, originals = setmetatable({}, {__mode = "k"}),
		pickupPending = false, lastPickup = -math.huge}, Inventory)
end

function Inventory:catalog()
	local items = workspace:FindFirstChild("Prison_ITEMS")
	local result = {}
	if not items then return result end
	for _, folderName in ipairs({"giver", "single"}) do
		local folder = items:FindFirstChild(folderName)
		if folder then
			for _, entry in ipairs(folder:GetChildren()) do
				local pickup = entry:FindFirstChild("ITEMPICKUP")
				if pickup then
					table.insert(result, {name = entry.Name, pickup = pickup, free = FREE_WEAPONS[entry.Name] == true})
				end
			end
		end
	end
	table.sort(result, function(a, b) return a.name < b.name end)
	return result
end

function Inventory:getWeapon(entry)
	if not (entry and entry.free == true and FREE_WEAPONS[entry.name]) then
		return false, "not on the known free-item candidate list"
	end
	local remotes = workspace:FindFirstChild("Remote")
	local handler = remotes and remotes:FindFirstChild("ItemHandler")
	local folder = workspace:FindFirstChild("Prison_ITEMS")
	if not (handler and handler:IsA("RemoteFunction") and folder and entry
		and typeof(entry.pickup) == "Instance" and entry.pickup:IsDescendantOf(folder)) then
		return false, "compatible pickup remote or item not found"
	end
	if self.pickupPending or os.clock() - self.lastPickup < 0.18 then
		return false, "wait for the previous pickup request"
	end
	self.pickupPending, self.lastPickup = true, os.clock()
	local ok, response = pcall(handler.InvokeServer, handler, entry.pickup)
	self.pickupPending = false
	if not ok then return false, "pickup call failed: " .. tostring(response) end
	if response == false then return false, "pickup rejected by the game server" end
	return true, "pickup requested; check backpack for server acceptance"
end

function Inventory:getFreeWeapons()
	local sent, rejected = 0, 0
	local backpack = self.hub.localPlayer:FindFirstChildOfClass("Backpack")
	local character = self.hub.localPlayer.Character
	for _, item in ipairs(self:catalog()) do
		if item.free and sent + rejected < 5
			and not (backpack and backpack:FindFirstChild(item.name))
			and not (character and character:FindFirstChild(item.name)) then
			local ok = self:getWeapon(item)
			if ok then sent += 1 else rejected += 1 end
			task.wait(0.2)
		end
	end
	if sent == 0 then return false, rejected > 0 and "free pickups unavailable or rejected" or "no unowned free pickups found" end
	return true, sent .. " pickup requests sent; check backpack for actual items"
end

function Inventory:modifyEquippedGun()
	local character = self.hub.localPlayer.Character
	local tool = character and character:FindFirstChildOfClass("Tool")
	local module = tool and tool:FindFirstChild("GunStates")
	if not (module and module:IsA("ModuleScript")) then return false, "equip a gun with gunstates first" end
	local ok, states = pcall(require, module)
	if not ok and type(getthreadidentity) == "function" and type(setthreadidentity) == "function" then
		local idOk, oldIdentity = pcall(getthreadidentity)
		if idOk and pcall(setthreadidentity, 2) then
			ok, states = pcall(require, module)
			pcall(setthreadidentity, oldIdentity)
		end
	end
	if not ok or type(states) ~= "table" or type(states.Damage) ~= "number"
		or type(states.FireRate) ~= "number" or type(states.Spread) ~= "number" then
		return false, "compatible gunstates unavailable in this executor/game"
	end
	if not self.originals[states] then
		self.originals[states] = {Damage = states.Damage, FireRate = states.FireRate, Spread = states.Spread}
	end
	local modified = pcall(function()
		states.Damage = self.hub.config.gunDamage
		states.FireRate = self.hub.config.gunInterval
		states.Spread = self.hub.config.gunSpread
	end)
	if not modified then
		pcall(function()
			for key, value in pairs(self.originals[states]) do states[key] = value end
		end)
		return false, "gunstates are read-only"
	end
	return true, "local gunstates updated; server may ignore these values"
end

function Inventory:restore()
	for states, original in pairs(self.originals) do
		pcall(function()
			for key, value in pairs(original) do states[key] = value end
		end)
	end
	self.originals = setmetatable({}, {__mode = "k"})
end

return Inventory
end
local Inventory = loadInventory(PrivateContext)

-- Vehicles.
local function loadVehicles(PrivateContextModule)
local getRig = PrivateContextModule.getRig

-- Vehicle controls require the occupant's network ownership for physics edits.
local Vehicles = {}
Vehicles.__index = Vehicles

function Vehicles.new(hub)
	return setmetatable({hub = hub, originalSeats = setmetatable({}, {__mode = "k"})}, Vehicles)
end

function Vehicles:nearestSeat(maximum)
	local _, _, root = getRig(self.hub.localPlayer)
	if not root then return nil end
	local closest, distance = nil, maximum
	for _, part in ipairs(workspace:GetDescendants()) do
		if part:IsA("VehicleSeat") and not part.Occupant then
			local difference = (root.Position - part.Position).Magnitude
			if difference < distance then closest, distance = part, difference end
		end
	end
	return closest
end

function Vehicles:quickEntry()
	local seat = self:nearestSeat(60)
	local _, humanoid = getRig(self.hub.localPlayer)
	if not (seat and humanoid) then return false, "no nearby available vehicle seat" end
	local moved, message = self.hub.travel:teleport(seat.CFrame * CFrame.new(0, 3, 0))
	if not moved then return false, message end
	local ok = pcall(seat.Sit, seat, humanoid)
	return ok, ok and "entry attempted; server may reject it" or "could not sit in vehicle"
end

function Vehicles:occupiedSeat()
	local _, humanoid = getRig(self.hub.localPlayer)
	local seat = humanoid and humanoid.SeatPart
	if seat and seat:IsA("VehicleSeat") and seat.Occupant == humanoid then return seat end
	return nil
end

function Vehicles:tune()
	local seat = self:occupiedSeat()
	if not seat then return false, "enter a vehicle first" end
	if type(isnetworkowner) ~= "function" then return false, "executor cannot confirm vehicle physics ownership" end
	local ok, owned = pcall(isnetworkowner, seat)
	if not ok or not owned then return false, "you do not own this vehicle's physics" end
	local saved, original = pcall(function()
		return {MaxSpeed = seat.MaxSpeed, Torque = seat.Torque, TurnSpeed = seat.TurnSpeed}
	end)
	if not saved then return false, "vehicle seat does not support these properties" end
	self.originalSeats[seat] = self.originalSeats[seat] or original
	local baseline = self.originalSeats[seat]
	local applied = pcall(function()
		seat.MaxSpeed = self.hub.config.vehicleSpeed
		seat.Torque = baseline.Torque * self.hub.config.vehicleHandling
		seat.TurnSpeed = baseline.TurnSpeed * self.hub.config.vehicleHandling
	end)
	if not applied then
		pcall(function()
			for key, value in pairs(self.originalSeats[seat]) do seat[key] = value end
		end)
		return false, "game did not allow local vehicle tuning"
	end
	return true, "local vehicle settings applied; server may override them"
end

function Vehicles:teleportSelected()
	local seat = self:occupiedSeat()
	local destination = self.hub.travel.selected
	if not (seat and destination) then return false, "enter a vehicle and choose a location first" end
	if type(isnetworkowner) ~= "function" then return false, "executor cannot confirm network ownership" end
	local ok, owned = pcall(isnetworkowner, seat)
	if not ok or not owned then return false, "you do not own this vehicle's physics" end
	local model = seat:FindFirstAncestorOfClass("Model")
	if not model then return false, "vehicle model not found" end
	local moved, errorMessage = pcall(model.PivotTo, model, destination.cframe * CFrame.new(0, 4, 0))
	return moved, moved and "vehicle moved locally; server may correct it" or tostring(errorMessage)
end

function Vehicles:triggerSpawn()
	local _, _, root = getRig(self.hub.localPlayer)
	if not root then return false, "character not ready" end
	for _, object in ipairs(workspace:GetDescendants()) do
		if object:IsA("ProximityPrompt") or object:IsA("ClickDetector") then
			local part = object.Parent
			if part and part:IsA("Attachment") then part = part.Parent end
			local label = ((part and part.Name or "") .. " " .. (part and part.Parent and part.Parent.Name or "")
				.. " " .. (object:IsA("ProximityPrompt") and object.ActionText or "")):lower()
			local maxDistance = math.min(16, object.MaxActivationDistance)
			if part and part:IsA("BasePart") and (label:find("vehicle") or label:find("car") or label:find("spawn"))
				and (part.Position - root.Position).Magnitude <= maxDistance then
				if object:IsA("ProximityPrompt") and type(fireproximityprompt) == "function" then
					local ok = pcall(fireproximityprompt, object)
					if ok then return true, "vehicle prompt attempted; check for a spawned car" end
				elseif object:IsA("ClickDetector") and type(fireclickdetector) == "function" then
					local ok = pcall(fireclickdetector, object)
					if ok then return true, "spawn button attempted; check for a vehicle" end
				end
			end
		end
	end
	return false, "no supported nearby spawn control; cannot spawn a vehicle from this client"
end

function Vehicles:restore()
	for seat, values in pairs(self.originalSeats) do
		if seat.Parent then
			pcall(function()
				for key, value in pairs(values) do seat[key] = value end
			end)
		end
	end
	self.originalSeats = setmetatable({}, {__mode = "k"})
end

return Vehicles
end
local Vehicles = loadVehicles(PrivateContext)

-- PrivateMenu.
local function loadPrivateMenu()
local PrivateMenu = {}

---Keep every category in one menu module while feature controllers stay separate.
---@param hub table
---@return table
function PrivateMenu.pages(hub)
	local config = hub.config
	local ui = hub.ui
	local function toggle(name, title, hint)
		ui:toggle(title, config[name], function(value) return hub:setFlag(name, value) end, hint)
	end
	local function slider(name, title, low, high, step, suffix, default)
		ui:slider(title, low, high, config[name], function(value)
			config[name] = value
			hub:onSettingChanged(name)
		end, function(value)
			return string.format(step < 1 and "%.2f" or "%d", value) .. (suffix or "")
		end, step, default)
	end
	return {
		{
			id = "home", label = "home", subtitle = "overview", keywords = "private server quick controls",
			render = function()
				ui:section("private session", "client-only tools · game-owned actions may be rejected")
				ui:info("place", game.PlaceId)
				ui:info("players", #hub.playersService:GetPlayers())
				slider("aimFov", "aim fov", 35, 350, 1, " px", 145)
				slider("movementSpeed", "movement speed", 16, 120, 1, " studs/s", 26)
				toggle("aimlock", "aimlock", "camera follows a selected player")
				toggle("playerEsp", "player esp")
				ui:section("quick actions", "stop all below disables every active mode")
				ui:action("request free pickups", "known candidate items; game decides access", function()
					hub:report(hub.inventory:getFreeWeapons())
				end, true)
				ui:action("open combat", nil, function() ui:selectPage("combat") end)
				ui:action("open teleport", nil, function() ui:selectPage("teleport") end)
			end,
		},
		{
			id = "combat", label = "combat", subtitle = "targeting", keywords = "aimbot aimlock silent aim rage bot taze arrest gun",
			render = function()
				ui:section("targeting", "camera assistance · shot-packet support is unverified")
				toggle("aimbot", "aimbot", "hold the aim key or use the touch switch")
				toggle("aimlock", "aimlock")
				toggle("silentAim", "silent aim", "only a recognized gun shot packet is changed")
				ui:info("shot status", hub.combat.shotStatus)
				ui:info("packets seen", hub.combat.shotsSeen)
				ui:info("packets changed", hub.combat.shotsChanged)
				ui:action("refresh shot status", nil, function() ui:refreshPage() end)
				toggle("rageBot", "rage bot", "aims camera and activates an equipped gun at a capped rate")
				toggle("autoTaze", "auto taze & arrest", "game taser / arrest remote; criminals only")
				toggle("teamCheck", "team check")
				toggle("wallCheck", "visibility check")
				ui:toggle("touch / manual aim", hub.combat.aimHeld, function(value)
					hub.combat.aimHeld = value
					return true
				end)
				slider("aimFov", "aim fov", 35, 350, 1, " px", 145)
				slider("aimSmooth", "aim smoothing", 0.04, 1, 0.01, "", 0.22)
				ui:action("aim part · " .. config.aimPart, "head / root part", function()
					config.aimPart = config.aimPart == "Head" and "HumanoidRootPart" or "Head"
					ui:refreshPage()
				end)
				ui:action("fire equipped tool", nil, function() hub:report(hub.combat:activate()) end, true)
				ui:section("target selection", "tap a player to track them explicitly")
				ui:action("closest to cursor", nil, function()
					hub.targeting.selected = nil
					ui:refreshPage()
				end)
				for _, player in ipairs(hub.playersService:GetPlayers()) do
					if player ~= hub.localPlayer then
						ui:action((hub.targeting.selected == player and "• " or "") .. player.DisplayName,
							"@" .. player.Name, function()
								hub.targeting.selected = player
								ui:refreshPage()
							end)
					end
				end
				ui:section("gun modification", "local gunstates only; server may reject stat changes")
				slider("gunDamage", "damage", 1, 100, 1, "", 30)
				slider("gunInterval", "fire interval", 0.05, 1, 0.01, "s", 0.15)
				slider("gunSpread", "spread", 0, 8, 0.1, "", 0)
				ui:action("apply to equipped gun", nil, function()
					hub:report(hub.inventory:modifyEquippedGun())
				end)
			end,
		},
		{
			id = "visuals", label = "visuals", subtitle = "esp", keywords = "player esp vehicle esp labels distance",
			render = function()
				ui:section("local visuals", "highlights and distance labels; no drawing api required")
				toggle("playerEsp", "player esp", "outline other players")
				toggle("vehicleEsp", "vehicle esp", "outline models containing a vehicle seat")
				ui:action("refresh visible objects", nil, function()
					hub.visuals:configure()
					hub:notify("esp refreshed", true)
				end)
			end,
		},
		{
			id = "movement", label = "movement", subtitle = "physics", keywords = "speed fly noclip infinite jump anti stun",
			render = function()
				ui:section("movement", "client-side movement may be corrected by the server")
				toggle("speedEnabled", "speed", "holds a configured walkspeed")
